-- Polestar.Dungeons.Opens: each dungeon's level range and the quests a
-- character could pick up for it, from a small table that is always loaded
-- (Dungeons/OpensData.lua, generated by `forge data codex` and `forge data
-- headsup`: rust/crates/forge-data/src/codex/opens.rs). The dungeon heads-up
-- (UI/DungeonToast.lua) reads only this, so a level-up never loads the Codex
-- pack or the quest database; the dungeon pages and the pick-up guides still
-- read the Codex.
--
-- A dungeon's quests for a side are kept as one string and read only when a
-- dungeon is checked. The table holds what never changes for a side (which of
-- the page quests are that side's, by Dungeons/Pickup.lua's rules; whether it
-- has a giver outside for that side; its chain); Plan applies what depends on
-- the character as Dungeons.PickupPlan does: race and class, quests done, in
-- the log or closed for good (`closedBy`), the level it opens at, the page
-- quests that have to be done first, and the errands done on the way to
-- another quest (not counted as quests of their own).
--
--   Dungeons.RegisterOpens(builtAt, dungeons)   -- OpensData.lua only
--   Dungeons.Opens.BuiltAt() -> the Codex build the table came from
--   Dungeons.Opens.List() -> { dungeon, ... } in level order; dungeon =
--       { key, name, minLevel, maxLevel, map, zone, zoneName } (names in the
--       client's language where known, as Dungeons.List)
--   Dungeons.Opens.Get(key) -> dungeon | nil
--   Dungeons.Opens.Find(text) -> key | nil      -- by name (either language) or key
--   Dungeons.Opens.Plan(key[, p]) -> { take, later, done, carried, ids } | nil
--       counts, as Dungeons.PickupPlan's #take, later, done and #carried;
--       ids: the quests to pick up
--   Dungeons.Opens.OnPage(key, id[, p]) -> whether quest id is one of the
--       dungeon's quests for the character's side
--   Dungeons.Opens.QuestXP(key[, p]) -> Levels.Run's summary | nil -- what
--       the side's quests still to do are worth, as Dungeons.QuestXP
--     p: Levels.Player() by default

local ADDON, ns = ...
local Dungeons = ns.Dungeons

local type, ipairs, pairs, tonumber, floor, max = type, ipairs, pairs, tonumber, math.floor, math.max
local find, lower, gmatch, sub, sort = string.find, string.lower, string.gmatch, string.sub, table.sort

local Opens = {}
Dungeons.Opens = Opens

local SIDE = { Alliance = "A", Horde = "H" }
local RACE_BIT = { Human = 1, Orc = 2, Dwarf = 4, NightElf = 8, Scourge = 16, Undead = 16, Tauren = 32, Gnome = 64, Troll = 128 }
local CLASS_BIT = {
	WARRIOR = 1, PALADIN = 2, HUNTER = 4, ROGUE = 8, PRIEST = 16,
	SHAMAN = 64, MAGE = 128, WARLOCK = 256, DRUID = 1024,
}
local CLASS_OF = {}
for k, b in pairs(CLASS_BIT) do CLASS_OF[b] = k end

local builtAt
local data = {} -- key -> { name, minLevel, maxLevel, map, zone, zoneName, A = rows, H = rows }

function Dungeons.RegisterOpens(at, dungeons)
	builtAt = at
	data = type(dungeons) == "table" and dungeons or {}
end

function Opens.BuiltAt() return builtAt end

local function player(p)
	return p or (ns.Levels and ns.Levels.Player and ns.Levels.Player()) or {}
end

local function done(id) return ns.Compat.IsQuestCompleted(id) and true or false end
local function inLog(id) return ns.Compat.IsOnQuest(id) and true or false end

local function hasBit(mask, b)
	return floor(mask / b) % 2 == 1
end

-- Lookup's maskBlocks: a mask that leaves out the character's race or class.
local function blocks(mask, bits, key)
	if not mask or mask <= 0 or not key then return false end
	local b = bits[key]
	if not b then return false end
	return not hasBit(mask, b)
end

local function idList(s)
	local out = {}
	for id in gmatch(s, "%d+") do out[#out + 1] = tonumber(id) end
	return out
end

-- One side's rows: { id, minLevel, level, xp, take (giver and a chain the
-- side can take), r, c, R, C (masks), x, w, v (id lists) }.
local function rows(e, side)
	local s = e and e[side]
	local out = {}
	if type(s) ~= "string" or s == "" then return out end
	for row in gmatch(s, "[^;]+") do
		local q, i = { take = true }, 0
		for field in gmatch(row, "[^,]+") do
			i = i + 1
			if i <= 4 then
				q[i] = tonumber(field)
			else
				local k, v = sub(field, 1, 1), sub(field, 2)
				if k == "g" then
					q.take = false
				elseif k == "x" or k == "w" or k == "v" then
					q[k] = idList(v)
				else
					q[k] = tonumber(v)
				end
			end
		end
		q.id, q.minLevel, q.level, q.xp = q[1], q[2], q[3], q[4]
		out[#out + 1] = q
	end
	return out
end

local function dungeon(key, e)
	local N = ns.Names
	local localised = N and N.Localised and N.Localised()
	local name, zoneName = e[1], e[6] ~= "" and e[6] or nil
	if localised then
		name = (e[4] and e[4] > 0 and N.Instance and N.Instance(e[4])) or name
		zoneName = (e[5] and e[5] > 0 and ns.Compat.MapName(e[5])) or zoneName
	end
	return {
		key = key, name = name or key, minLevel = e[2], maxLevel = e[3] and e[3] > 0 and e[3] or nil,
		map = e[4], zone = e[5] and e[5] > 0 and e[5] or nil, zoneName = zoneName,
	}
end

function Opens.Get(key)
	local e = key ~= nil and data[key]
	return e and dungeon(key, e) or nil
end

function Opens.List()
	local out = {}
	for key, e in pairs(data) do out[#out + 1] = dungeon(key, e) end
	sort(out, function(a, b)
		if a.minLevel ~= b.minLevel then return a.minLevel < b.minLevel end
		return a.key < b.key
	end)
	return out
end

function Opens.Find(text)
	if type(text) ~= "string" or text == "" then return nil end
	local want, hit = lower(text), nil
	for _, d in ipairs(Opens.List()) do
		local n, en = lower(d.name), lower(data[d.key][1] or d.key)
		if n == want or en == want or d.key == want then return d.key end
		if not hit and (find(n, want, 1, true) or find(en, want, 1, true)) then hit = d.key end
	end
	return hit
end

-- The character's rows for a dungeon: its side's, without those its race or
-- class can't take (Pickup.lua's notYours).
local function yours(key, p)
	local side = SIDE[p.faction or ""]
	if not side then return nil end
	local out = {}
	for _, q in ipairs(rows(data[key], side)) do
		if not (blocks(q.r, RACE_BIT, p.race) or blocks(q.c, CLASS_BIT, p.class)) then out[#out + 1] = q end
	end
	return out
end

local function allDone(list)
	for _, id in ipairs(list or {}) do
		if not done(id) then return false end
	end
	return true
end

local function closed(q)
	for _, by in ipairs(q.x or {}) do
		if done(by) or inLog(by) then return true end
	end
	return false
end

function Opens.Plan(key, p)
	local e = key ~= nil and data[key]
	if not e then return nil end
	p = player(p)
	local list = yours(key, p)
	if not list then return nil end
	local reach = max(p.level or 1, e[2] or 1)
	local plan = { take = 0, later = 0, done = 0, carried = 0 }
	local take, onTheWay = {}, {}
	for _, q in ipairs(list) do
		if done(q.id) then
			plan.done = plan.done + 1
		elseif inLog(q.id) then
			plan.carried = plan.carried + 1
		elseif closed(q) then
			plan.done = plan.done + 1
		elseif (q.minLevel or 1) > reach then
			plan.later = plan.later + 1
		elseif q.take and allDone(q.w) and not (blocks(q.R, RACE_BIT, p.race) or blocks(q.C, CLASS_BIT, p.class)) then
			take[#take + 1] = q
			for _, id in ipairs(q.v or {}) do
				if not done(id) then onTheWay[id] = true end
			end
		end
	end
	-- A quest done on the way to a later one is not a take of its own, nor carried.
	plan.ids = {}
	for _, q in ipairs(take) do
		if not onTheWay[q.id] then
			plan.take = plan.take + 1
			plan.ids[plan.take] = q.id
		end
	end
	for _, q in ipairs(list) do
		if onTheWay[q.id] and inLog(q.id) then plan.carried = plan.carried - 1 end
	end
	return plan
end

function Opens.OnPage(key, id, p)
	if not (key and data[key] and id) then return false end
	local side = SIDE[player(p).faction or ""]
	if not side then return false end
	for _, q in ipairs(rows(data[key], side)) do
		if q.id == id then return true end
	end
	return false
end

-- Dungeons.QuestXP over the side's quests: each with its level, XP and
-- classes, from the lowest level a quest still to do opens at.
function Opens.QuestXP(key, p)
	if not (key and data[key]) then return nil end
	local Levels = ns.Levels
	if not (Levels and Levels.Run) then return nil end
	p = player(p)
	local side = SIDE[p.faction or ""]
	if not side then return nil end
	local quests, start = {}, nil
	for _, q in ipairs(rows(data[key], side)) do
		local classes
		if q.c then
			classes = {}
			for b, k in pairs(CLASS_OF) do
				if hasBit(q.c, b) then classes[#classes + 1] = k end
			end
		end
		quests[#quests + 1] = { id = q.id, level = q.level, xp = q.xp and q.xp > 0 and q.xp or nil, classes = classes }
		if not done(q.id) and q.minLevel then start = start and math.min(start, q.minLevel) or q.minLevel end
	end
	return Levels.Run(quests, p, start)
end
